const input = $input.first().json;
const body = input.body || input;

// 주간 날짜 범위 계산 (이번 주 월~금, UTC)
const now = new Date();
const dayOfWeek = now.getUTCDay();
const daysFromMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
const monday = new Date(now);
monday.setUTCDate(now.getUTCDate() - daysFromMonday);
monday.setUTCHours(0, 0, 0, 0);

const owner = $env.GITHUB_OWNER || 'hanhosunglgu';
let repos = [];
try {
  const raw = $env.GITHUB_REPOS || '["WBS_Check"]';
  repos = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch(e) { repos = ['WBS_Check']; }

const boardId    = body.board_id    || $env.JIRA_BOARD_ID    || '8207';
const baseUrl    = $env.JIRA_BASE_URL    || 'https://lgucorp.atlassian.net';
const ddaRepo    = $env.DESIGN_DOC_REPO  || 'hanhosunglgu/WBS_Check';
const ddaPath    = $env.DESIGN_DOC_PATH  || 'docs/design';

return [{ json: {
  owner,
  repos,
  boardId,
  baseUrl,
  ddaRepo,
  ddaPath,
  week_start: monday.toISOString(),
  week_end:   now.toISOString(),
  triggered_by: body.triggered_by || 'manual'
} }];

const grc = $input.first().json;
const params = $('Init Params').first().json;

// GRC 결과 파싱 — 실패 시 기본값
const backend  = grc.backend  || [];
const frontend = grc.frontend || [];
const config   = grc.config   || [];
const mobile   = grc.mobile   || [];

const allCommitMessages = grc.all_commit_messages || [];
const totalCommits  = grc.total_commit_count || 0;
const maxActiveDays = grc.max_active_days    || 0;
const commitStats   = grc.commit_stats       || {};

return [{ json: {
  owner:            params.owner,
  repos:            params.repos,
  boardId:          params.boardId,
  baseUrl:          params.baseUrl,
  ddaRepo:          params.ddaRepo,
  ddaPath:          params.ddaPath,
  week_start:       params.week_start,
  week_end:         params.week_end,
  // GRC 분류 결과
  backend_repos:    backend,
  frontend_repos:   frontend,
  config_repos:     config,
  mobile_repos:     mobile,
  has_backend:      backend.length  > 0,
  has_frontend:     frontend.length > 0,
  has_config:       config.length   > 0,
  has_mobile:       mobile.length   > 0,
  // Commit 집계
  all_commit_messages: allCommitMessages,
  total_commits:    totalCommits,
  max_active_days:  maxActiveDays,
  commit_stats:     commitStats,
  grc_error:        grc.error || null
} }];

// 6개 Agent 결과 수집 — 부분 실패 시 기본값으로 대체
const items = $input.all();
const grcState = $('Parse GRC Result').first().json;

// agent_id 기준으로 결과 맵 구성
const resultMap = {};
for (const item of items) {
  const d = item.json;
  const id = d.agent_id || 'unknown';
  resultMap[id] = d;
}

// 기본값 팩토리
const defaultAgent = (id, repo_type) => ({
  agent_id: id,
  repo: 'N/A',
  repo_type,
  call_flow: [],
  design_gaps: [],
  commit_count: 0,
  active_days: 0,
  error: 'agent_skipped'
});

// Agent 실패 판단:
// 1. agent_id 없음 → webhook 비활성/빈 응답 (neverError:true 환경)
// 2. error 필드 존재 → 내부 에러 명시
// 3. 필수 식별 필드 부재 → 응답 구조 불완전
const isRawFailed = (raw) => {
  if (!raw) return true;
  // agent_id가 없으면 비활성 webhook의 빈 응답
  if (!raw.agent_id) return true;
  // error 필드가 있으면 실패
  if (raw.error && raw.error !== null && raw.error !== 'null') return true;
  return false;
};

// 각 agent별 필수 식별 필드 검사
const isJraFailed  = (raw) => isRawFailed(raw) || (raw && !raw.agent_id && Object.keys(raw).length === 0);
const isCodeFailed = (raw) => isRawFailed(raw);

const rawJra = resultMap['WBS-JRA'];
const rawDda = resultMap['WBS-DDA'];
const rawBak = resultMap['WBS-BAK'];
const rawFrt = resultMap['WBS-FRT'];
const rawCfg = resultMap['WBS-CFG'];
const rawMob = resultMap['WBS-MOB'];

const jra = rawJra && !isRawFailed(rawJra)
  ? rawJra
  : { agent_id:'WBS-JRA', total_tickets:0, done:0, in_review:0, in_progress:0, todo:0, sp_total:0, sp_burned:0, sp_burned_rate:0, ticket_done_rate:0, jira_commit_map:{}, error: rawJra?.error || 'agent_unavailable' };

const dda = rawDda && !isRawFailed(rawDda)
  ? rawDda
  : { agent_id:'WBS-DDA', endpoints:[], tables:[], sequences:[], error: rawDda?.error || 'agent_unavailable' };

const bak = rawBak && !isRawFailed(rawBak)
  ? rawBak
  : { ...defaultAgent('WBS-BAK','backend'), error: rawBak?.error || 'agent_unavailable' };

const frt = rawFrt && !isRawFailed(rawFrt)
  ? rawFrt
  : { ...defaultAgent('WBS-FRT','frontend'), error: rawFrt?.error || 'agent_unavailable' };

const cfg = rawCfg && !isRawFailed(rawCfg)
  ? rawCfg
  : { ...defaultAgent('WBS-CFG','config'), error: rawCfg?.error || 'agent_unavailable' };

const mob = rawMob && !isRawFailed(rawMob)
  ? rawMob
  : { ...defaultAgent('WBS-MOB','mobile'), error: rawMob?.error || 'agent_unavailable' };

// 실패한 Agent 목록 — error 필드 기반 (agent_unavailable 포함)
const failedAgents = [jra,dda,bak,frt,cfg,mob]
  .filter(a => a.error && a.error !== null && a.error !== 'null')
  .map(a => a.agent_id);

return [{ json: {
  // 파라미터 전달
  owner:              grcState.owner,
  repos:              grcState.repos,
  boardId:            grcState.boardId,
  week_start:         grcState.week_start,
  week_end:           grcState.week_end,
  total_commits:      grcState.total_commits,
  max_active_days:    grcState.max_active_days,
  all_commit_messages: grcState.all_commit_messages,
  // Agent 결과
  jra, dda, bak, frt, cfg, mob,
  failed_agents: failedAgents
} }];

// Task 3.3.1: Call Flow 재구성 — Mobile/Frontend → Backend → Config/DB 레이어 정렬
const d = $input.first().json;
const { bak, frt, mob, dda } = d;

// 설계 문서의 시퀀스 (DDA)
const designSequences = dda.sequences || [];
const designEndpoints = dda.endpoints || [];

// 각 Agent의 call_flow 수집
const rawFlows = [
  ...(mob.call_flow || []).map(f => ({ ...f, layer: 'mobile' })),
  ...(frt.call_flow || []).map(f => ({ ...f, layer: 'frontend' })),
  ...(bak.call_flow || []).map(f => ({ ...f, layer: 'backend' }))
];

// 실제 API 엔드포인트 (BAK)
const actualEndpoints = bak.extracted_endpoints || bak.call_flow?.map(f => f.to) || [];

// 이번 주 전체 커밋이 0개이면 endpoint 비교 생략 (코드 분석 결과 없음은 미구현이 아님)
const totalCommits = (bak.commit_count || 0) + (frt.commit_count || 0) +
                     ((d.cfg || {}).commit_count || 0) + (mob.commit_count || 0);
const noCommitsThisWeek = totalCommits === 0;

// 설계 문서 endpoints가 n8n webhook paths인지 확인 (예: /webhook/wbs-xxx)
// n8n webhook paths는 실제 애플리케이션 코드에 없으므로 비교 대상에서 제외
const toStr = e => (typeof e === 'string' ? e : e.path || e.endpoint || JSON.stringify(e)).toLowerCase();
const isWebhookPath = e => toStr(e).includes('/webhook/');
const comparableDesignEndpoints = designEndpoints.filter(e => !isWebhookPath(e));
const skipEndpointComparison = noCommitsThisWeek || comparableDesignEndpoints.length === 0;

// 설계 vs 실제 엔드포인트 비교
const designSet  = new Set(comparableDesignEndpoints.map(toStr));
const actualSet  = new Set(actualEndpoints.map(e => (typeof e === 'string' ? e : JSON.stringify(e)).toLowerCase()));

const missingInActual = skipEndpointComparison ? [] : [...designSet].filter(e => !actualSet.has(e));
const extraInActual   = skipEndpointComparison ? [] : [...actualSet].filter(e => !designSet.has(e));

// 통합 Call Flow 맵 (레이어별 정렬)
const integratedFlow = {
  design_sequences: designSequences,
  mobile_flows:     mob.call_flow   || [],
  frontend_flows:   frt.call_flow   || [],
  frontend_api_calls: frt.api_calls || [],
  backend_flows:    bak.call_flow   || [],
  actual_endpoints: actualEndpoints,
  design_endpoints: designEndpoints
};

return [{ json: {
  ...d,
  integrated_flow:     integratedFlow,
  missing_in_actual:   missingInActual,
  extra_in_actual:     extraInActual,
  endpoint_match_rate: designSet.size > 0
    ? Math.round((designSet.size - missingInActual.length) / designSet.size * 100)
    : 100
} }];

// Task 3.3.2: 전체 design_gaps[] 통합 — 모든 Agent Gap 합산 + 중복 제거
const d = $input.first().json;
const { bak, frt, cfg, mob, missing_in_actual, extra_in_actual } = d;

const allGaps = [];

// 각 Agent의 design_gaps 수집
for (const [agentId, agent] of [
  ['WBS-BAK', bak],
  ['WBS-FRT', frt],
  ['WBS-CFG', cfg],
  ['WBS-MOB', mob]
]) {
  const gaps = agent.design_gaps || [];
  for (const gap of gaps) {
    allGaps.push({
      source_agent:      agentId,
      item:              gap.item || gap.description || 'Unknown',
      discrepancy_type:  gap.discrepancy_type || gap.type || 'unknown',
      severity:          (gap.severity || 'medium').toLowerCase(),
      design:            gap.design || '',
      actual:            gap.actual || '',
      description:       gap.description || gap.item || ''
    });
  }
}

// Call Flow 불일치를 Gap으로 추가
for (const endpoint of (missing_in_actual || [])) {
  allGaps.push({
    source_agent:     'WBS-ORK',
    item:             endpoint,
    discrepancy_type: 'missing_implementation',
    severity:         'high',
    design:           endpoint,
    actual:           'not found in code',
    description:      `설계 문서에 정의된 엔드포인트가 실제 코드에 없음: ${endpoint}`
  });
}
for (const endpoint of (extra_in_actual || [])) {
  allGaps.push({
    source_agent:     'WBS-ORK',
    item:             endpoint,
    discrepancy_type: 'undocumented_implementation',
    severity:         'medium',
    design:           'not in design doc',
    actual:           endpoint,
    description:      `코드에는 있지만 설계 문서에 없는 엔드포인트: ${endpoint}`
  });
}

// 중복 제거 (item + source_agent 기준)
const seen = new Set();
const uniqueGaps = allGaps.filter(g => {
  const key = `${g.source_agent}::${g.item}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

const highGaps   = uniqueGaps.filter(g => g.severity === 'high');
const mediumGaps = uniqueGaps.filter(g => g.severity === 'medium');
const lowGaps    = uniqueGaps.filter(g => g.severity === 'low');

return [{ json: {
  ...d,
  all_gaps:        uniqueGaps,
  gap_count:       uniqueGaps.length,
  high_gap_count:  highGaps.length,
  medium_gap_count: mediumGaps.length,
  low_gap_count:   lowGaps.length
} }];

// Task 3.3.3: OpenAI API 호출을 위한 요청 구성
const d = $input.first().json;
const { all_gaps, dda } = d;

// Gap이 없으면 API 호출 스킵
if (!all_gaps || all_gaps.length === 0) {
  return [{ json: { ...d, _skip_ollama: true } }];
}

const gapSummary = all_gaps.slice(0, 15).map((g, i) =>
  `${i+1}. [${g.severity.toUpperCase()}] ${g.source_agent} - ${g.item}: ${g.description}`
).join('\n');

const designItems = (dda.endpoints || []).length + (dda.tables || []).length + (dda.sequences || []).length;

const prompt = `You are a software design review assistant. Analyze the following design gaps found between design documents and actual implementation.

Design document items: ${designItems} total (endpoints: ${(dda.endpoints||[]).length}, tables: ${(dda.tables||[]).length}, sequences: ${(dda.sequences||[]).length})

Found gaps:
${gapSummary}

For each gap, classify intent as one of: "intentional_improvement", "oversight", "missing_implementation".
Return ONLY JSON array (no explanation):
[{"item": "...", "intent": "...", "severity": "high|medium|low", "recommendation": "..."}]`;

return [{ json: {
  ...d,
  _skip_ollama: false,
  _ollama_prompt: prompt,
  _design_items_count: designItems,
  model: 'gpt-4.1-mini',
  messages: [{ role: 'user', content: prompt }],
  stream: false
} }];

// Ollama 결과 파싱 및 Gap에 intent_analysis 필드 추가
const ollamaResult = $input.first().json;
const prevData = $('Build Gap Analysis Prompt').first().json;

let analyzedGaps = prevData.all_gaps || [];

try {
  const raw = ollamaResult.choices[0].message.content || '';
  // JSON 배열 추출
  const match = raw.match(/\[.*\]/s);
  if (match) {
    const parsed = JSON.parse(match[0]);
    // item 기준으로 Gap에 intent 보강
    const intentMap = {};
    for (const p of parsed) {
      intentMap[p.item] = { intent: p.intent, recommendation: p.recommendation };
    }
    analyzedGaps = analyzedGaps.map(g => ({
      ...g,
      intent_analysis:  intentMap[g.item]?.intent     || 'unknown',
      recommendation:   intentMap[g.item]?.recommendation || ''
    }));
  }
} catch(e) {
  // 파싱 실패 시 기본값 유지
  analyzedGaps = analyzedGaps.map(g => ({ ...g, intent_analysis: 'unknown', recommendation: '' }));
}

return [{ json: { ...prevData, all_gaps: analyzedGaps } }];

// Gap 없는 경우 — 분석 없이 통과
const d = $input.first().json;
return [{ json: { ...d, all_gaps: [] } }];

// Task 3.3.4: 설계 적합성 점수 계산
// 공식: (전체 설계 항목 - High Gap 수) / 전체 설계 항목 × 100
const d = $input.first().json;
const { all_gaps, dda, endpoint_match_rate } = d;

const designItems = (dda.endpoints||[]).length + (dda.tables||[]).length + (dda.sequences||[]).length;
const highGaps    = (all_gaps||[]).filter(g => g.severity === 'high').length;
const mediumGaps  = (all_gaps||[]).filter(g => g.severity === 'medium').length;
const lowGaps     = (all_gaps||[]).filter(g => g.severity === 'low').length;

let designScore;
if (designItems === 0) {
  designScore = highGaps === 0 ? 100 : Math.max(0, 100 - highGaps * 15);
} else {
  designScore = Math.max(0, Math.round((designItems - highGaps) / designItems * 100));
}

// 설계 적합성 등급
let designGrade;
if (designScore >= 90)      designGrade = 'GREEN';
else if (designScore >= 70) designGrade = 'YELLOW';
else                        designGrade = 'RED';

return [{ json: {
  ...d,
  design_score:      designScore,
  design_grade:      designGrade,
  design_items_total: designItems,
  high_gap_count:    highGaps,
  medium_gap_count:  mediumGaps,
  low_gap_count:     lowGaps,
  gap_count:         (all_gaps||[]).length
} }];

// Task 3.4: 진척률 최종 계산
// 가중치: Jira 티켓 완료율 40% + SP 소진률 40% + Commit 빈도 20%
const d = $input.first().json;
const { jra, total_commits, max_active_days } = d;

// Jira 티켓 완료율 (40%)
const ticketDoneRate  = jra.ticket_done_rate || 0;  // 0~100
const jiraScore       = ticketDoneRate * 0.4;

// SP 소진률 (40%)
// SP 데이터 없을 경우 티켓 완료율로 대체
const spBurnedRate    = jra.sp_burned_rate > 0 ? jra.sp_burned_rate : ticketDoneRate;
const spScore         = spBurnedRate * 0.4;

// GitHub Commit 빈도 (20%) — 활성 개발일 / 5일
const activeDayRate   = Math.min(100, Math.round((max_active_days / 5) * 100));
const commitScore     = activeDayRate * 0.2;

// 전체 진척률
const totalProgress   = Math.round(jiraScore + spScore + commitScore);

// 진척률 등급 (Green/Yellow/Red)
let progressGrade;
if (totalProgress >= 70)      progressGrade = 'GREEN';
else if (totalProgress >= 40) progressGrade = 'YELLOW';
else                          progressGrade = 'RED';

// 이번 주 날짜 범위 (YYYY-MM-DD)
const weekStart = d.week_start ? d.week_start.substring(0, 10) : 'N/A';
const weekEnd   = d.week_end   ? d.week_end.substring(0, 10)   : 'N/A';

return [{ json: {
  // 기본 메타
  agent_id:           'WBS-ORK',
  week_start:         weekStart,
  week_end:           weekEnd,
  // 진척률
  total_progress:     totalProgress,
  progress_grade:     progressGrade,
  jira_score:         Math.round(jiraScore),
  sp_score:           Math.round(spScore),
  commit_score:       Math.round(commitScore),
  // Jira 현황
  sprint_id:          jra.sprint_id   || null,
  sprint_name:        jra.sprint_name || 'N/A',
  total_tickets:      jra.total_tickets   || 0,
  done_tickets:       jra.done            || 0,
  in_progress_tickets: jra.in_progress    || 0,
  in_review_tickets:  jra.in_review       || 0,
  todo_tickets:       jra.todo            || 0,
  sp_total:           jra.sp_total        || 0,
  sp_burned:          jra.sp_burned       || 0,
  sp_burned_rate:     jra.sp_burned_rate  || 0,
  ticket_done_rate:   ticketDoneRate,
  jira_commit_map:    jra.jira_commit_map || {},
  linked_ticket_count: jra.linked_ticket_count || 0,
  no_commit_issues:   jra.no_commit_issues || [],
  incomplete_tickets: (jra.incomplete_tickets || []).slice(0, 10),
  // GitHub 활동
  total_commits:      total_commits    || 0,
  max_active_days:    max_active_days  || 0,
  active_day_rate:    activeDayRate,
  // 설계 적합성
  design_score:       d.design_score,
  design_grade:       d.design_grade,
  design_items_total: d.design_items_total,
  high_gap_count:     d.high_gap_count,
  medium_gap_count:   d.medium_gap_count,
  low_gap_count:      d.low_gap_count,
  gap_count:          d.gap_count,
  all_gaps:           (d.all_gaps || []).slice(0, 20),
  // 통합 Call Flow
  integrated_flow:    d.integrated_flow    || {},
  endpoint_match_rate: d.endpoint_match_rate || 100,
  missing_in_actual:  d.missing_in_actual  || [],
  extra_in_actual:    d.extra_in_actual    || [],
  // 실패 Agent
  failed_agents:      d.failed_agents      || [],
  error:              null
} }];

// Manual Trigger / Schedule Trigger 결과도 동일한 응답 출력
const d = $input.first().json;
console.log('=== WBS-ORK 최종 결과 ===');
console.log(`진척률: ${d.total_progress}% [${d.progress_grade}]`);
console.log(`설계 적합성: ${d.design_score}% [${d.design_grade}]`);
console.log(`Jira: 완료 ${d.done_tickets}/${d.total_tickets} (${d.ticket_done_rate}%)`);
console.log(`Commit: ${d.total_commits}회, 활성 ${d.max_active_days}일`);
console.log(`Gap: 총 ${d.gap_count}건 (High:${d.high_gap_count}, Medium:${d.medium_gap_count}, Low:${d.low_gap_count})`);
return [$input.first()];
